import { execFileSync } from "node:child_process";
import { mkdirSync, mkdtempSync, rmSync, symlinkSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { build } from "vite";
import { installerVersion } from "./register-candidate.mjs";

const LOG_PREFIX = "field-change-reader";
const SCRIPT = ".github/scripts/field-change-reader.mjs";
const RELEASE_TAG_RE = /^pos-v(?:0|[1-9]\d*)\.(?:0|[1-9]\d*)\.(?:0|[1-9]\d*)$/;
const RUN_NUMBER_RE = /^[1-9]\d*$/;
const REPO_ROOT = fileURLToPath(new URL("../../", import.meta.url));
const READERS_DIR = join(
  REPO_ROOT,
  "packages/contracts/src/sync/test-support/field-change-readers",
);
const SOURCES_AT_TAG = [
  "packages/domain/package.json",
  "packages/domain/src",
  "packages/contracts/package.json",
  "packages/contracts/src",
];

class Refusal extends Error {}

function git(args, cwd) {
  return execFileSync("git", args, { cwd, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] });
}

function commitOfTag(repoDir, tag) {
  try {
    return git(["rev-parse", "--verify", "--quiet", `refs/tags/${tag}^{commit}`], repoDir).trim();
  } catch {
    throw new Refusal(`${LOG_PREFIX}: the repository has no tag ${tag}`);
  }
}

function reportedVersion(repoDir, commit, runNumber) {
  const registerPackage = JSON.parse(git(["show", `${commit}:apps/pos/package.json`], repoDir));
  return installerVersion({ packageVersion: registerPackage.version, runNumber });
}

function extractSources(repoDir, commit, into) {
  const archive = join(into, "sources.tar");
  git(["archive", "--format=tar", `--output=${archive}`, commit, ...SOURCES_AT_TAG], repoDir);
  execFileSync("tar", ["-xf", archive, "-C", into]);
  mkdirSync(join(into, "node_modules/@purosur"), { recursive: true });
  symlinkSync(join(into, "packages/domain"), join(into, "node_modules/@purosur/domain"));
}

async function bundleChangesPageSchema(sourceRoot) {
  const entry = join(sourceRoot, "field-change-reader.ts");
  writeFileSync(
    entry,
    'export { changesPageSchema } from "./packages/contracts/src/sync/changes.ts";\n',
  );
  const [output] = await build({
    configFile: false,
    logLevel: "warn",
    root: sourceRoot,
    resolve: { conditions: ["@purosur/source"] },
    build: {
      write: false,
      minify: false,
      lib: { entry, formats: ["es"], fileName: () => "reader.js" },
      rolldownOptions: { cwd: sourceRoot, external: ["zod"] },
    },
  });
  return output.output[0].code;
}

async function generateFieldChangeReader({ repoDir, tag, runNumber, outDir }) {
  if (!RELEASE_TAG_RE.test(tag)) {
    throw new Refusal(`${LOG_PREFIX}: ${JSON.stringify(tag)} is not a pos release tag pos-vX.Y.Z`);
  }
  if (!RUN_NUMBER_RE.test(runNumber)) {
    throw new Refusal(`${LOG_PREFIX}: ${JSON.stringify(runNumber)} is not a run number`);
  }
  const commit = commitOfTag(repoDir, tag);
  const version = reportedVersion(repoDir, commit, runNumber);
  const sourceRoot = mkdtempSync(join(tmpdir(), "field-change-reader-"));
  try {
    extractSources(repoDir, commit, sourceRoot);
    const code = await bundleChangesPageSchema(sourceRoot);
    const header = `// Generated by \`node ${SCRIPT} ${tag} ${runNumber}\` from the tag ${tag}: the change pages the register that reports ${version} reads.\n`;
    const file = join(outDir, `${version}.js`);
    writeFileSync(file, header + code);
    return { version, file };
  } finally {
    rmSync(sourceRoot, { recursive: true, force: true });
  }
}

export async function runCli({
  argv = process.argv.slice(2),
  repoDir = REPO_ROOT,
  outDir = READERS_DIR,
  log = console.log,
  logError = console.error,
} = {}) {
  if (argv.length !== 2) {
    logError(
      `${LOG_PREFIX}: usage: node ${SCRIPT} <tag> <run number>, a pos release tag and the run number of the packaging run that built its installer`,
    );
    return 1;
  }
  const [tag, runNumber] = argv;
  try {
    const { version, file } = await generateFieldChangeReader({ repoDir, tag, runNumber, outDir });
    log(`${LOG_PREFIX}: wrote the reader of ${version} to ${file}`);
    return 0;
  } catch (error) {
    if (!(error instanceof Refusal)) {
      throw error;
    }
    logError(error.message);
    return 1;
  }
}

if (import.meta.main) {
  runCli().then(
    (exitCode) => process.exit(exitCode),
    (error) => {
      console.error(error);
      process.exit(1);
    },
  );
}
